  ui_story_5055_50550702_30_dialog_content = "Hmm, você consegue dizer em qual casa eu moro pelo cheiro, não é?",
  ui_story_5055_50550702_31_dialog_content = "Se você não encontrar nada para comer, venha me ver, tá bom?",
