  ui_story_5055_50550702_35_dialog_content = "*choramingar*",
  ui_story_5055_50550702_36_dialog_content = "Ei, por que você está se agarrando ao meu sapato como se não quisesse que eu vá embora?",
  ui_story_5055_50550702_37_dialog_content = "*choramingar e latir*",
  ui_story_5055_50550702_38_dialog_content = "Tá bom, tá bom, eu realmente tenho algo muito importante para fazer agora.",
  ui_story_5055_50550702_39_dialog_content = "Eu prometo que voltarei para você e até podemos patrulhar juntos!",
  ui_story_5055_50550702_40_dialog_content = "*continua choramingando*",
  ui_story_5055_50550801_1_dialog_content = "(Que filhotinho pobre era aquele. Provavelmente ninguém queria se aproximar antes, senão não seria tão apegado.)",
  ui_story_5055_50550801_2_dialog_content = "(Ele não esperaria lá atrás por mim, e eu não posso levá-lo ao médico...)",
  ui_story_5055_50550801_3_dialog_content = "(Então tive que pegar o caminho mais longo para perder isso.)",
  ui_story_5055_50550801_4_dialog_content = "(Eu me sinto mal com isso, mas ele tem um olfato aguçado e provavelmente vai alcançar em breve.)",
  ui_story_5055_50550801_5_dialog_content = "(Eu tenho que terminar o exame de saúde antes disso.)",
  ui_story_5055_50550801_6_dialog_content = "Não! Socorro!",
  ui_story_5055_50550801_7_dialog_content = "A clínica do doutor está pegando fogo! Nós precisamos de ajuda! Agora!",
  ui_story_5055_50550801_8_dialog_content = "O quê?!",
  ui_story_5055_50550801_9_dialog_content = "Doutor, docente, onde você tá?",
  ui_story_5055_50550801_10_dialog_content = "<size=45>Doutor? Professor? Consegue me ouvir?</size>",
  ui_story_5055_50550801_11_dialog_content = "Alguém nos ajude!",
  ui_story_5055_50550801_12_dialog_content = "Alguém ainda está lá dentro!",
  ui_story_5055_50550801_13_dialog_content = "Eu tenho que entrar!",
  ui_story_5055_50550801_14_dialog_content = "<color=#e8d9bb>Bum!</color>",
  ui_story_5055_50550801_15_dialog_content = "... Por favor! Alguém!",
  ui_story_5055_50550801_16_dialog_content = "Docente, sou eu, Eve! Onde você tá?",
  ui_story_5055_50550801_17_dialog_content = "...",
  ui_story_5055_50550801_18_dialog_content = "O quê? Está aqui também?",
  ui_story_5055_50550802_1_dialog_content = "Você está bem, senhor?",
  ui_story_5055_50550802_2_dialog_content = "D-Não chegue mais perto!",
  ui_story_5055_50550802_3_dialog_content = "Senhor? Sou eu, Eve, estou aqui para tirá-lo daqui.",
  ui_story_5055_50550802_4_dialog_content = "Não... Socorro! Socorro!",
  ui_story_5055_50550802_5_dialog_content = "Minha professora nunca havia entrado em pânico assim antes... Deve ter sido assustada por aquela boneca de urso.",
  ui_story_5055_50550802_6_dialog_content = "E onde está o doutor...?",
  ui_story_5055_50550802_7_dialog_content = "Foi tudo ideia dela! Não minha! NÃO MINHA!",
  ui_story_5055_50550802_8_dialog_content = "Por favor, não me machuque—!",
  ui_story_5055_50550802_9_dialog_content = "Fique tranquilo, senhor. Eu sou Eve, seu aluno. Eu nunca vou te machucar!",
  ui_story_5055_50550802_10_dialog_content = "Alguém estava tentando te machucar? A pessoa também colocou fogo na clínica?",
  ui_story_5055_50550802_11_dialog_content = "Foi você...",
  ui_story_5055_50550802_12_dialog_content = "Hã?",
  ui_story_5055_50550802_13_dialog_content = "Foi você, seu monstro, que colocou fogo neste lugar!",
  ui_story_5055_50550802_14_dialog_content = "O quê...?",
  ui_story_5055_50550802_15_dialog_content = "<color=#e8d9bb>*estalos e crepitações*</color>",
  ui_story_5055_50550802_16_dialog_content = "(Fogo... Está tão quente...)",
  ui_story_5055_50550802_17_dialog_content = "(De onde eu já vi isso... antes...)",
  ui_story_5055_50550802_18_dialog_content = "(A mesma... fogo...)",
  ui_story_5055_50550802_19_dialog_content = "(O teto está caindo... Evetudo está cantando ao redor... Muita fumaça para respirar...)",
  ui_story_5055_50550802_20_dialog_content = "(Há alguém... no fogo...)",
  ui_story_5055_50550802_21_dialog_content = "(Alguém que nunca esquecerei...)",
  ui_story_5055_50550802_22_dialog_content = "(Ela está...)",
  ui_story_5055_50550802_23_dialog_content = "(Ela está...!)",
  ui_story_5055_50550802_24_dialog_content = "É você! Não acredito que você voltou.",
  ui_story_5055_50550802_25_dialog_content = "Estou aqui para te salvar, Doutor...",
  ui_story_5055_50550802_26_dialog_content = "Foi você quem ateou fogo neste lugar e arruinou tudo o que eu trabalhei tanto para construir?",
  ui_story_5055_50550802_27_dialog_content = "Não...",
  ui_story_5055_50550802_28_dialog_content = "Eu te concedi poderes melhores, mas o que você fez? Olhe a bagunça que você fez!",
  ui_story_5055_50550802_29_dialog_content = "Minha pesquisa, meus dados, tudo que construí ao longo de todos esses anos... e até mesmo este corpo, todos consumidos pelas chamas.",
  ui_story_5055_50550802_30_dialog_content = "Diga-me, Eve—o pecado de me destruir! O que você vai pagar por isso?",
  ui_story_5055_50550802_31_dialog_content = "<color=#e8d9bb>Bum! *Estalos*</color>",
  ui_story_5055_50550802_32_dialog_content = "Não sou eu, não sou eu!",
  ui_story_5055_50550802_33_dialog_content = "Fogo...! Mas eu me lembro do fogo, queimando como um ódio eterno...",
  ui_story_5055_50550802_34_dialog_content = "Por que o fogo aconteceu, por que haveria ódio em mim?",
  ui_story_5055_50550802_35_dialog_content = "Eu só vim aqui para um acompanhamento...",
  ui_story_5055_50550802_36_dialog_content = "Eu não quero machucar ninguém... Eu só quero ser o Eve que protege todo mundo!",
  ui_story_5055_50550802_37_dialog_content = "Hehehe... Hahahaha!",
  ui_story_5055_50550802_38_dialog_content = "Não tem coragem de admitir, hã? Não era você o anjinho perfeito que se auto-proclamou?",
  ui_story_5055_50550802_39_dialog_content = "Tudo bem então, você será enterrado junto com os meus dados de pesquisa!",
  ui_story_5055_50550802_40_dialog_content = "Uau!",
  ui_story_5055_50550802_41_dialog_content = "O cachorrinho vermelho?",
  ui_story_5055_50550802_42_dialog_content = "Não, não se aproxime... É muito perigoso, mantenha-se afastado!",
  ui_story_5055_50550802_43_dialog_content = "Au-au!",
  ui_story_5055_50550802_44_dialog_content = "Hahaha, mais um que não vê a hora de encontrar seu destino, hã?",
  ui_story_5055_50550802_45_dialog_content = "Vamos! Trazem! Estou louco para testar essa adaga!",
  ui_story_5055_50550802_46_dialog_content = "Awooo!!!",
  ui_story_5055_50550802_47_dialog_content = "O quê?!",
  ui_story_5055_50550802_48_dialog_content = "O prédio está desabando... Cuidado!",
  ui_story_5055_50550802_49_dialog_content = "<color=#e8d9bb>Bum!</color>",
  ui_story_5055_50550802_50_dialog_content = "(Estou soterrado sob o prédio desabado?)",
  ui_story_5055_50550802_51_dialog_content = "(Não ouça mais o doutor e o cachorro, apenas o barulho das chamas devorando tudo.)",
  ui_story_5055_50550802_52_dialog_content = "Mas eu ainda estou respirando...",
  ui_story_5055_50550802_53_dialog_content = "Eu ainda estou vivo?",
  ui_story_5055_50550802_54_dialog_content = "De onde vieram essas videiras e por que estavam ao meu redor?",
  ui_story_5055_50550802_55_dialog_content = "Há um aroma diferente de queimado. Na verdade, é distinto e agradável.",
  ui_story_5055_50550802_56_dialog_content = "É um cheiro agradável... Cheira como... flores?",
  ui_story_5055_50550802_57_dialog_content = "Eu me lembro agora. As coisas brancas, finas e delicadas fora das videiras são flores!",
  ui_story_5055_50550802_58_dialog_content = "É você, a grama com tumores no meu bolso?",
  ui_story_5055_50550802_59_dialog_content = "Aquele bulbo branco não era um tumor, mas um broto... Como eu não reconheci isso?",
  ui_story_5055_50550802_60_dialog_content = "Obrigado por me salvar novamente.",
  ui_story_5055_50550802_61_dialog_content = "Mas e quanto ao professor, doutor e o filhote vermelho...?",
  ui_story_5055_50550802_62_dialog_content = "Foi por minha causa...?",
  ui_story_5055_50550802_63_dialog_content = "<color=#e8d9bb>Bum!!!</color>",
  ui_story_5055_50550802_64_dialog_content = "Grama, não! Não me deixe... Não...",
  ui_story_5055_50550802_65_dialog_content = "Você tolo, por que se sacrificar para me salvar do fogo ardente e do prédio desmoronando?",
  ui_story_5055_50550802_66_dialog_content = "Se você ficasse no meu bolso, provavelmente conseguiria e criaria raízes no solo cinzento...",
  ui_story_5055_50550802_67_dialog_content = "Realmente valho o sacrifício?",
  ui_story_5055_50550802_68_dialog_content = "...",
  ui_story_5055_50550802_69_dialog_content = "Quem está aí?",
  ui_story_5055_50550802_70_dialog_content = "?!!",
  ui_story_5055_50550802_71_dialog_content = "Foi você quem ateou fogo neste lugar e arruinou tudo o que eu trabalhei tanto para construir?",
  ui_story_5055_50550802_72_dialog_content = "Foi você, seu monstro, que colocou fogo neste lugar!",
  ui_story_5055_50550802_73_dialog_content = "Você... provocou o incêndio?",
  ui_story_5055_50550802_74_dialog_content = "Sim.",
  ui_story_5055_50550802_75_dialog_content = "Quem é você? Como você se parece comigo?",
  ui_story_5055_50550802_76_dialog_content = "Eu sou você.",
  ui_story_5055_50550802_77_dialog_content = "Sou a dor que você escondeu, o medo que não conseguiu enfrentar, a memória que se recusou a lembrar.",
  ui_story_5055_50550802_78_dialog_content = "Estou aqui para dizer que não ignore...",
  ui_story_5055_50550802_79_dialog_content = "Não ignore a realidade.",
  ui_story_5055_50551102_1_dialog_content = "Eu nunca soube que havia um lugar assim na Rua Cauda.",
  ui_story_5055_50551102_2_dialog_content = "O quê?",
  ui_story_5055_50551102_3_dialog_content = "Lá... Por que aquela garota está sendo mantida lá?",
  ui_story_5055_50551102_4_dialog_content = "Tantos tubos e instrumentos conectados ao corpo dela... Coitada! Alguém não vai salvá-la?",
  ui_story_5055_50551102_5_dialog_content = "Isso não é uma cela, mas sim uma sala de tratamento para manter ela e todos ao redor em segurança.",
  ui_story_5055_50551102_6_dialog_content = "Sala de tratamento? E eu vejo um urso de pelúcia lá dentro!",
  ui_story_5055_50551102_7_dialog_content = "É o brinquedo favorito dela e o companheiro mais leal.",
  ui_story_5055_50551102_8_dialog_content = "Quanto à garota, ninguém a conhece melhor do que você.",
  ui_story_5055_50551102_9_dialog_content = "Eu conheço ela? Ela parece tão fraca, vazia e o rosto dela...",
  ui_story_5055_50551102_10_dialog_content = "Parece igual ao seu!",
  ui_story_5055_50551102_11_dialog_content = "E a minha também!",
  ui_story_5055_50551102_12_dialog_content = "É o verdadeiro Eve, o Eve no mundo real.",
  ui_story_5055_50551102_13_dialog_content = "O verdadeiro Eve? Quer dizer que você e eu somos falsos?",
  ui_story_5055_50551102_14_dialog_content = "Não somos falsos. O que é falso é o mundo em que estamos agora.",
  ui_story_5055_50551102_15_dialog_content = "Este é o mundo falso que o doutor criou para nós através do hipnotismo, um mundo de falsa felicidade.",
  ui_story_5055_50551102_16_dialog_content = "Ela nos enganou desde o começo. Ela nunca quis nos tratar.",
  ui_story_5055_50551102_17_dialog_content = "Ela removeu as personalidades em excesso de nossa memória que ameaçariam seu experimento.",
  ui_story_5055_50551102_18_dialog_content = "Então ela reescreveu a história para nós, onde nossos pais estão vivos, somos curados, saudáveis e vivemos felizes para sempre.",
  ui_story_5055_50551102_19_dialog_content = "Todos para nos manter sãos enquanto ela realizava todos os tipos de experimentos imorais em nós.",
  ui_story_5055_50551102_20_dialog_content = "...",
  ui_story_5055_50551102_21_dialog_content = "EveEmbora tenhamos deixado o doutor para trás eventualmente...",
  ui_story_5055_50551102_22_dialog_content = "Este mundo ainda nos controla, impedindo-nos de ver o mundo real.",
  ui_story_5055_50551102_23_dialog_content = "Estou muito feliz vivendo neste mundo... Então, mesmo a alegria não é real?",
  ui_story_5055_50551102_24_dialog_content = "Eu sei que você esqueceu seu passado insuportável, e isso é bom em certos aspectos.",
  ui_story_5055_50551102_25_dialog_content = "Mas você não pode ficar aqui. Precisamos voltar ao mundo real.",
  ui_story_5055_50551102_26_dialog_content = "Voltar...?",
  ui_story_5055_50551102_27_dialog_content = "Mas eu não quero. Eu só quero desenhar, regar a grama, patrulhar fora da vila e proteger todo mundo...",
  ui_story_5055_50551102_28_dialog_content = "Por que me prender assim? Eu não quero, eu não quero!",
  ui_story_5055_50551102_29_dialog_content = "Mas você deve ficar lá dentro ou vai destruir tudo!",
  ui_story_5055_50551102_30_dialog_content = "Você quer uma repetição da tragédia que aconteceu em sua cidade natal?",
  ui_story_5055_50551102_31_dialog_content = "Tragédia, cidade natal? Como assim?",
  ui_story_5055_50551102_32_dialog_content = "Você quer ver seus entes queridos sendo machucados por você de novo?",
  ui_story_5055_50551102_33_dialog_content = "Irmão, e Dawn.",
  ui_story_5055_50551102_34_dialog_content = "Irmão? Eu tenho um irmão? Dawn...?",
  ui_story_5055_50551102_35_dialog_content = "Ah, minha cabeça está doendo de novo!",
  ui_story_5055_50551102_36_dialog_content = "Vejo que você ainda não consegue se lembrar.",
  ui_story_5055_50551102_37_dialog_content = "Ao contrário de você, eu nunca me integrei a este mundo, então ainda me lembro de tudo que passamos.",
  ui_story_5055_50551102_38_dialog_content = "Eles são tudo o que temos.",
  ui_story_5055_50551102_39_dialog_content = "Mas estamos presos neste mundo falso, incapazes de ver aqueles que realmente nos amaram.",
  ui_story_5055_50551102_40_dialog_content = "Então eu odeio o doutor que apagou isso... E odeio você também!",
  ui_story_5055_50551102_41_dialog_content = "Eu te odeio por esquecer que eles já existiram e aceitar essa falsa realidade em completa ignorância.",
  ui_story_5055_50551102_42_dialog_content = "!!!",
  ui_story_5055_50551102_43_dialog_content = "Vejo que tenho que fazer você lembrar de tudo para convencê-lo.",
  ui_story_5055_50551102_44_dialog_content = "Bem, siga-me até nossa cidade natal então.",
  ui_story_5055_50551102_45_dialog_content = "Aquele que destruímos com nossas próprias mãos.",
  ui_story_5055_50551102_46_dialog_content = "Cidade natal... Mas não é isso?",
  ui_story_5055_50551102_47_dialog_content = "Me siga.",
  ui_story_5055_50551301_1_dialog_content = "<color=#e8d9bb>Bum!</color>",
  ui_story_5055_50551301_2_dialog_content = "Ei, um vulcão acabou de entrar em erupção?",
  ui_story_5055_50551301_3_dialog_content = "A coisa quente rolando por todo o chão é lava, não é?",
  ui_story_5055_50551301_4_dialog_content = "Consigo sentir uma onda de calor após a outra, mesmo daqui.",
  ui_story_5055_50551301_5_dialog_content = "Ainda vamos?",
  ui_story_5055_50551301_6_dialog_content = "Estamos quase lá, nossa casa.",
  ui_story_5055_50551301_7_dialog_content = "Nossa casa está dentro do vulcão?",
  ui_story_5055_50551301_8_dialog_content = "Vou te esperar bem ali.",
  ui_story_5055_50551301_9_dialog_content = "Ei, espere!",
  ui_story_5055_50551301_10_dialog_content = "Graah!!",
  ui_story_5055_50551301_11_dialog_content = "Existem Eclipsitas até mesmo em um ambiente tão hostil?",
  ui_story_5055_50551301_12_dialog_content = "Essas Eclipsitas... Elas estão me lembrando de algo...",
  ui_story_5055_50551301_13_dialog_content = "O dia em que invadiram a aldeia e a reduziram a pó...",
  ui_story_5055_50551301_14_dialog_content = "E o dia em que eu obtive o poder monstruoso e me descontrolei como eles fizeram.",
  ui_story_5055_50551301_15_dialog_content = "O Darkflow entrou no meu corpo através de uma pequena semente...",
  ui_story_5055_50551301_16_dialog_content = "Senti-me quente e entorpecido por dentro, como se cem estrelas explodissem em silêncio.",
  ui_story_5055_50551301_17_dialog_content = "Eu queria perder aquele poder atormentador, só para perceber que ele me levantou do chão!",
  ui_story_5055_50551301_18_dialog_content = "Eu entrei em pânico quando fiquei pairando no ar. Tudo o que eu queria era agarrar e segurar algo.",
  ui_story_5055_50551301_19_dialog_content = "Acabei pegando corrente telúrica.",
  ui_story_5055_50551301_20_dialog_content = "Interrompi o campo magnético, injetei energia na crosta, fiz o vulcão entrar em erupção e transformei a casa nisso...",
  ui_story_5055_50551301_21_dialog_content = "O poder monstruoso escravizou-me no meu momento mais fraco e indefeso!",
  ui_story_5055_50551301_22_dialog_content = "Perdi toda a razão como eles e destruí tudo sem remorso...",
  ui_story_5055_50551301_23_dialog_content = "Mereço continuar vivendo assim?",
  ui_story_5055_50551402_1_dialog_content = "Arf, arf...",
  ui_story_5055_50551402_2_dialog_content = "Está ficando mais difícil... e mais difícil... respirar...",
  ui_story_5055_50551402_3_dialog_content = "Por que eu tenho que... lutar contra Eclipsitas nessas condições...?",
  ui_story_5055_50551402_4_dialog_content = "Não estou tão longe que não possa voltar atrás.",
  ui_story_5055_50551402_5_dialog_content = "Mas...",
  ui_story_5055_50551402_6_dialog_content = "Devo voltar?",
  ui_story_5055_50551402_7_dialog_content = "EveNesta linha do tempo feliz foi destruída pelas chamas.",
  ui_story_5055_50551402_8_dialog_content = "Aquele outro eu disse que ninguém esperava que eu fosse um excelente guerreiro na realidade.",
  ui_story_5055_50551402_9_dialog_content = "O doutor estava apenas usando meu corpo, mas eu desferi uma vingança desenfreada sobre ela.",
  ui_story_5055_50551402_10_dialog_content = "É essa a perspectiva que devo enfrentar?",
  ui_story_5055_50551402_11_dialog_content = "Retornando a uma realidade infeliz, cheia de ódio e dor, suportando a solidão e o tormento do confinamento.",
  ui_story_5055_50551402_12_dialog_content = "E se eu perder o controle novamente...?",
  ui_story_5055_50551402_13_dialog_content = "Eu posso ferir ainda mais pessoas e transformar o ambiente em um inferno assim...",
  ui_story_5055_50551402_14_dialog_content = "Não, eu absolutamente não posso permitir que isso aconteça.",
  ui_story_5055_50551402_15_dialog_content = "Se essa é a verdadeira natureza, preciso evitá-la de alguma forma!",
  ui_story_5055_50551801_1_dialog_content = "Arf, arf...",
  ui_story_5055_50551801_2_dialog_content = "Aqui está você. Esta é a nossa cidade natal...",
  ui_story_5055_50551801_3_dialog_content = "Ravina Olho Vermelho.",
  ui_story_5055_50551801_4_dialog_content = "Finalmente, você se lembrou.",
  ui_story_5055_50551801_5_dialog_content = "Assim que pisei aqui, o passado inundou minha mente em fragmentos semelhantes a bolhas, surgindo um por um em minha mente.",
  ui_story_5055_50551801_6_dialog_content = "Eu finalmente percebi que aquelas visões assustadoras que me ocorreram eram todas reais.",
  ui_story_5055_50551801_7_dialog_content = "Este já foi um assentamento autossuficiente, mas agora só restam pedras soltas e solos queimados...",
  ui_story_5055_50551801_8_dialog_content = "Lava em erupção, cinzas encobrindo, terra partida... Tudo por minha causa.",
  ui_story_5055_50551801_9_dialog_content = "É assim por minha causa.",
  ui_story_5055_50551801_10_dialog_content = "Maytalvez seja melhor eu ficar aqui para sempre.",
  ui_story_5055_50551801_11_dialog_content = "...",
  ui_story_5055_50551801_12_dialog_content = "Você quer que eu volte ao mundo real, não é?",
  ui_story_5055_50551801_13_dialog_content = "Mas você também sabe que provavelmente vou causar mais problemas para aqueles ao meu redor.",
  ui_story_5055_50551801_14_dialog_content = "Então é melhor eu ficar? Dessa forma, o verdadeiro eu nunca vai acordar e nunca perderá o controle...",
  ui_story_5055_50551801_15_dialog_content = "Se não voltarmos, não há chance de sair da sala de tratamento.",
  ui_story_5055_50551801_16_dialog_content = "Mas eu não consigo me controlar...",
  ui_story_5055_50551801_17_dialog_content = "Não no passado, não agora e provavelmente não no futuro também...",
  ui_story_5055_50551801_18_dialog_content = "Posso aceitar a impotência e suportar aquelas memórias horríveis...",
  ui_story_5055_50551801_19_dialog_content = "Mas não posso deixar as pessoas que me amam se machucarem repetidamente!",
  ui_story_5055_50551801_20_dialog_content = "Se você desistir, isso ainda machucará aqueles que nos amaram.",
  ui_story_5055_50551801_21_dialog_content = "Devemos voltar.",
  ui_story_5055_50551801_22_dialog_content = "É ainda mais difícil encarar a dura realidade após acordar de um sonho doce.",
  ui_story_5055_50551801_23_dialog_content = "Eu não tenho o que é preciso para suportar todo esse choque de uma vez só...",
  ui_story_5055_50551801_24_dialog_content = "Mas eu preciso agradecer por me contar minha verdadeira realidade e por me mostrar que ainda existem pessoas que realmente me amam.",
  ui_story_5055_50551801_25_dialog_content = "Mas eu... simplesmente não consigo voltar com você.",
  ui_story_5055_50551801_26_dialog_content = "Sim, você pode. Nós podemos.",
  ui_story_5055_50551801_27_dialog_content = "Se é isso que você insiste, minha única escolha é...",
  ui_story_5055_50551801_28_dialog_content = "Para te destruir!",
  ui_story_5055_50551801_29_dialog_content = "Você é a única chave para eu retornar à realidade. Posso me trancar aqui para sempre se me livrar de você.",
  ui_story_5055_50551801_30_dialog_content = "Me mate e nunca mais verá aqueles que nos amam.",
  ui_story_5055_50551801_31_dialog_content = "EveEmbora meu irmão, Dawn, e outros não estejam aqui, está tudo bem. Eu não preciso de ninguém.",
  ui_story_5055_50551801_32_dialog_content = "Estou pronto para ficar sozinho.",
  ui_story_5055_50551801_33_dialog_content = "Isso é muito melhor do que perder a cabeça e destruir tudo que amo com minhas próprias mãos...",
  ui_story_5055_50551801_34_dialog_content = "Uma ameaça perigosa como eu deve permanecer adormecida e não acordar.",
  ui_story_5055_50551801_35_dialog_content = "Sei que você tem boas intenções. Obrigado, mas desculpe.",
  ui_story_5055_50551801_36_dialog_content = "Eu preciso te matar.",
  ui_story_5055_50551801_37_dialog_content = "Eu sou você. Você perderá seu poder me matando e, na realidade, provavelmente morrerá.",
  ui_story_5055_50551801_38_dialog_content = "É mesmo? Mas isso não é ainda melhor?",
  ui_story_5055_50551801_39_dialog_content = "Eu me cansei muito disso...",
  ui_story_5055_50551801_40_dialog_content = "Agora, vamos encerrar.",
  ui_story_5055_50551802_1_dialog_content = "Termine tudo, acabe com tudo.",
  ui_story_5055_50551802_2_dialog_content = "A lava parou de fluir. A fumaça preta parou no ar. EveOs Eclipsitas próximos pararam...",
  ui_story_5055_50551802_3_dialog_content = "Está tão quieto.",
  ui_story_5055_50551802_4_dialog_content = "Suficiente para ouvir minha batida de coração.",
  ui_story_5055_50551802_5_dialog_content = "Mas meu coração deve parar de bater em breve.",
  ui_story_5055_50551802_6_dialog_content = "Ei, ouço um som, o som de algo estourando...",
  ui_story_5055_50551802_7_dialog_content = "São as bolhas de memória estourando na minha cabeça.",
  ui_story_5055_50551802_8_dialog_content = "Sem mais medo, sem mais tristeza e sem mais dor...",
  ui_story_5055_50551802_9_dialog_content = "Mas por quê? Por que as lágrimas não param de cair?",
  ui_story_5055_50551802_10_dialog_content = "A dor surda no meu peito... Será que é o poder me deixando?",
  ui_story_5055_50551802_11_dialog_content = "Ou seria isso que eles chamam de saudade...?",
  ui_story_5055_50551802_12_dialog_content = "Irmão, Dawn... No final, ainda não consigo lembrar de seus rostos.",
  ui_story_5055_50551802_13_dialog_content = "Mas sinto tanto a sua falta, e a dos outros também...",
  ui_story_5055_50551802_14_dialog_content = "Não acha que estou chorando porque não quero te deixar. Eu-Eu estou chorando porque...",
  ui_story_5055_50551802_15_dialog_content = "De alegria! Finalmente, eu protegi todos vocês do meu próprio jeito!",
  ui_story_5055_50551802_16_dialog_content = "Veja, eu não me esqueci da alegria. A alegria também traz lágrimas.",
  ui_story_5055_50551802_17_dialog_content = "Espero que todos fiquem felizes por mim...",
  ui_story_5055_50551802_18_dialog_content = "Finalmente, posso sair sem dor, tranquilamente, silenciosamente...",
  ui_story_5055_50551802_19_dialog_content = "Essa é a melhor maneira que consigo pensar para retribuir seu amor.",
  ui_story_5055_50551802_20_dialog_content = "...",
  ui_story_5055_50551802_21_dialog_content = "<color=#e8d9bb>*resmunga*</color>",
  ui_story_5055_50551802_22_dialog_content = "O que houve?",
  ui_story_5055_50551802_23_dialog_content = "<size=45><color=#e8d9bb>Roncando!</color></size>",
  ui_story_5055_50551802_24_dialog_content = "EveTudo está desaparecendo, até mesmo meu poder, então nada deveria estar afetando essa realidade...",
  ui_story_5055_50551802_25_dialog_content = "A menos...",
  ui_story_5055_50551802_26_dialog_content = "A menos que o verdadeiro eu esteja morrendo.",
  ui_story_5055_50551802_27_dialog_content = "Não tente desperdiçar seu esforço tentando me salvar, por favor...",
  ui_story_5055_50551802_28_dialog_content = "Só me deixe ir...",
  ui_story_5055_50551802_29_dialog_content = "Não, você ainda está vivo e deve viver!",
  ui_story_5055_50551802_30_dialog_content = "Quem é este?",
  ui_story_5055_50551802_31_dialog_content = "Não se lembra de mim, Eve? Sou PlayerName. Eu sou PlayerName!",
  ui_story_5055_50551802_32_dialog_content = "PlayerName? Eu já ouvi a história do Príncipe Encantado salvando uma princesa em coma... Você é o meu Príncipe Encantado?",
  ui_story_5055_50551802_33_dialog_content = "Mas você não precisa trazer à tona meu passado, porque até eu sei...",
  ui_story_5055_50551802_34_dialog_content = "Alguém como eu não vale a pena salvar...",
  ui_story_5055_50551802_35_dialog_content = "Mas nós realmente precisamos da sua ajuda!",
  ui_story_5055_50551802_36_dialog_content = "Minha ajuda? O que posso fazer?",
  ui_story_5055_50551802_37_dialog_content = "Você pode fazer mais do que imaginou!",
  ui_story_5055_50551802_38_dialog_content = "Mas meu poder é maligno e incontrolável. Vou destruir tudo...",
  ui_story_5055_50551802_39_dialog_content = "Nem o doutor nem os Eclipsitas forçaram isso em você!",
  ui_story_5055_50551802_40_dialog_content = "É a sua habilidade natural que estava adormecida dentro de você!",
  ui_story_5055_50551802_41_dialog_content = "É forte o suficiente para nos proteger a todos!",
  ui_story_5055_50551802_42_dialog_content = "Lembre-se da verdadeira fonte do seu poder!",
  ui_story_5055_50551802_43_dialog_content = "Estamos todos esperando você voltar...",
  ui_story_5055_50551802_44_dialog_content = "<size=45>Acorda!</size>",
  ui_story_5055_50551802_45_dialog_content = "<size=45>Acorda!</size> ACORDA! <size=30>Acorda...</size>",
  ui_story_5055_50551901_1_dialog_content = "...",
  ui_story_5055_50551901_2_dialog_content = "Entendi... Finalmente encontrei a peça perdida!",
  ui_story_5055_50551901_3_dialog_content = "Essas são as pessoas mais importantes para mim...",
  ui_story_5055_50551901_4_dialog_content = "Agora é hora de juntar os retratos de todos!",
  ui_story_5055_50551901_5_dialog_content = "Isso pode ser...",
  ui_story_5055_50551901_6_dialog_content = "Hmm, vale a pena tentar.",
  ui_story_5055_50551901_7_dialog_content = "...",
  ui_story_5055_50551901_8_dialog_content = "Ei, isso é...",
  ui_story_5055_50551901_9_dialog_content = "Sinsa... Dawn... PlayerName...!",
  ui_story_5055_50551901_10_dialog_content = "Todos os rostos deles! Finalmente me lembro como todos eles se parecem.",
  ui_story_5055_50551901_11_dialog_content = "O que está acontecendo, por que não consigo controlar minhas lágrimas hoje...",
  ui_story_5055_50551901_12_dialog_content = "Eu vejo que na verdade eu queria ver todos mais do que eu acreditava.",
  ui_story_5055_50551901_13_dialog_content = "Eu pensei que tinha decidido ficar aqui de uma vez por todas...",
  ui_story_5055_50551901_14_dialog_content = "Não, você queria sair, acordar e ir passear com seu melhor traje.",
  ui_story_5055_50551901_15_dialog_content = "Você pode visitar uma pradaria repleta de flores ou uma exuberante floresta tropical.",
  ui_story_5055_50551901_16_dialog_content = "Eu pensei que meu poder havia me transformado em um monstro que só machucaria as pessoas...",
  ui_story_5055_50551901_17_dialog_content = "Não, você nos protegerá com seu poder.",
  ui_story_5055_50551901_18_dialog_content = "Enquanto você confiar na pessoa que pode se tornar. A grandeza e glória dela serão o seu futuro.",
  ui_story_5055_50551901_19_dialog_content = "Eu pensei que se eu ficasse longe de todos e estivesse sozinho, não causaria problemas...",
  ui_story_5055_50551901_20_dialog_content = "Não, você nunca esteve sozinho.",
  ui_story_5055_50551901_21_dialog_content = "EveTodos estiveram aqui o tempo todo.",
  ui_story_5055_50551901_22_dialog_content = "Eve!",
  ui_story_5055_50551901_23_dialog_content = "Eve...",
  ui_story_5055_50551901_24_dialog_content = "Eve, Eve, Eve...",
  ui_story_5055_50551901_25_dialog_content = "Eve!",
  ui_story_5055_50551901_26_dialog_content = "Irmão...",
  ui_story_5055_50551901_27_dialog_content = "Minha família, meus amigos, minha saudade do mundo real...",
  ui_story_5055_50551901_28_dialog_content = "Estou recuperando tudo, recuperando tudo de volta!",
  ui_story_5055_50551901_29_dialog_content = "Mas o eu atual não está completo. Eu destruí partes de mim.",
  ui_story_5055_50551901_30_dialog_content = "Não posso sair e te ver novamente...",
  ui_story_5055_50551901_31_dialog_content = "Sim, você pode. Você sempre pôde.",
  ui_story_5055_50551901_32_dialog_content = "Hã?",
  ui_story_5055_50551901_33_dialog_content = "Você voltou! Eu pensei que você tinha ido embora de vez!",
  ui_story_5055_50551901_34_dialog_content = "Você pode sentir medo novamente, não pode?",
  ui_story_5055_50551901_35_dialog_content = "Depois do que eu fiz com você... Obrigado por voltar para mim.",
  ui_story_5055_50551901_36_dialog_content = "Mas vejo que nunca consegui eliminar minha ansiedade e medo.",
  ui_story_5055_50551901_37_dialog_content = "Devo ser grato por não conseguir conquistá-los?",
  ui_story_5055_50551901_38_dialog_content = "Você não tem apenas medo de perder o controle do seu poder, você tem medo de muitas outras coisas.",
  ui_story_5055_50551901_39_dialog_content = "Insetos que mordem, ferrões afiados, lugares escuros, irmão se machucando, ninguém prestando atenção em você...",
  ui_story_5055_50551901_40_dialog_content = "Pare, apenas pare! Você precisa continuar?",
  ui_story_5055_50551901_41_dialog_content = "Mas tudo bem. Isso faz de você quem você é... O verdadeiro você, o verdadeiro nós.",
  ui_story_5055_50551901_42_dialog_content = "Apenas aqueles que compreenderam o amor e tinham algo para amar podiam sentir medo e tristeza.",
  ui_story_5055_50551901_43_dialog_content = "O poder que tenho agora vem do amor em seu coração.",
  ui_story_5055_50551901_44_dialog_content = "Você vai embora de novo?",
  ui_story_5055_50551901_45_dialog_content = "Sou você. Sou parte de nós. Nunca irei embora.",
  ui_story_5055_50551901_46_dialog_content = "Mas eu me tornarei você, transformando-nos em mim e dando a você a força para seguir em frente.",
  ui_story_5055_50551901_47_dialog_content = "Nós podemos... Posso sair daqui agora?",
  ui_story_5055_50551901_48_dialog_content = "Sim. Acordaremos no mundo real muito em breve.",
  ui_story_5055_50551901_49_dialog_content = "Tenho outra pergunta! PlayerName disse que precisava da minha ajuda.",
  ui_story_5055_50551901_50_dialog_content = "Você conhece a realidade melhor do que eu, então me diga como posso ajudar depois que eu acordar?",
  ui_story_5055_50551901_51_dialog_content = "Você já está ajudando a controlar a tempestade. Mas há uma coisa que todos querem de você.",
  ui_story_5055_50551901_52_dialog_content = "Eles querem que você viva uma vida feliz e despreocupada.",
  ui_story_5055_50551901_53_dialog_content = "Tudo bem se você for imaturo, não for forte o suficiente ou precisar de muita prática para dominar seu poder.",
  ui_story_5055_50551901_54_dialog_content = "A chave é perseverar e viver.",
  ui_story_5055_50551901_55_dialog_content = "Acorde! Eve!",
  ui_story_5055_50551901_56_dialog_content = "Olha, alguém está te esperando.",
  ui_story_5055_50551901_57_dialog_content = "Isso é PlayerName, irmão, Dawn, e os caras da Chave Rediesel...",
  ui_story_5055_50551901_58_dialog_content = "Eles precisam de mim!",
  ui_story_5055_50551901_59_dialog_content = "Tenho medo de muitas coisas na realidade lá fora, mas também há muitas coisas que eu amo!",
  ui_story_5055_50551901_60_dialog_content = "O amor é muito mais precioso do que o ódio.",
  ui_story_5055_50551901_61_dialog_content = "Eu tenho pessoas que amo, lugares que amo, então...",
  ui_story_5055_50551901_62_dialog_content = "Vou continuar vivendo!",
  ui_story_5055_50551901_63_dialog_content = "Muito em breve, abrirei meus olhos...",
  ui_story_5055_50551901_64_dialog_content = "Então, vou dar minha primeira respiração com tudo que tenho e valorizar minha vida.",
  ui_story_5055_50551901_65_dialog_content = "Eu vou viver, assim como aqueles que me amam!",
  ui_story_5055_50559901_1_dialog_content = "Esta peça...",
  ui_story_5055_50559901_2_dialog_content = "<color=#e8d9bb>Parece que este pedaço de papel foi rasgado de um livro ilustrado.</color>",
  ui_story_5055_50559901_3_dialog_content = "<color=#e8d9bb>Ele retrata vagamente a cabeça de uma mulher misteriosa usando um casaco branco.</color>",
  ui_story_5055_50559901_4_dialog_content = "Não é essa a parte que está faltando no meu livro ilustrado! O formato se encaixa... mas por que a cor parece estranha...?",
  ui_story_5055_50559901_5_dialog_content = "Deixe-me ver o que tem nele...",
  ui_story_5055_50559901_6_dialog_content = "É o meu médico!",
  ui_story_5055_50559901_7_dialog_content = "É o bom doutor que me curou! Hehe, bem, isso faz muito sentido.",
  ui_story_5055_50559901_8_dialog_content = "Afinal, é tudo graças a ela que estou livre agora. Eu devia querer agradecer a ela por me dar um lar tão feliz.",
  ui_story_5055_50559901_9_dialog_content = "Pensando bem, nem me lembro se ela alguma vez sorriu. Acho que ela era muito rígida ou tinha uma qualidade um tanto estranha.",
  ui_story_5055_50559901_10_dialog_content = "Ei, isso é o que eles chamam de... ironia?",
  ui_story_5055_50559901_11_dialog_content = "Mas eu sinto que ela deve ter sorrido para mim pelo menos uma vez...",
  ui_story_5055_50559901_12_dialog_content = "Eh, por que de repente parece frio aqui no deserto... Eu deveria procurar as outras peças enquanto posso!",
  ui_story_5055_50559901_13_dialog_content = "Só espere até eu colocar as mãos em quem rasgou este livro ilustrado! Não acredito que realmente rasgaram o rosto do doutor! O que há de errado com eles?!",
  ui_story_5055_50559901_14_dialog_content = "Rasgaram tanto que nem consigo juntar de novo...",
  ui_story_5055_50559901_15_dialog_content = "Espere um pouco, agora que eu olho bem para essa rasgadura, parece que há uma fileira de marcas de dentes aqui...",
  ui_story_5055_50559901_16_dialog_content = "Será que não era a sombra, mas algum tipo de bicho roendo esse pedaço?",
  ui_story_5055_50559901_17_dialog_content = "Erm, mas se fosse apenas uma criatura, então eu simplesmente largaria. Eu não posso exatamente perseguir um animal...",
  ui_story_5055_50559902_1_dialog_content = "<color=#e8d9bb>Na folha de papel está a imagem de um vaso de flores de cerâmica contendo um pequeno monte de terra.</color>",
  ui_story_5055_50559902_2_dialog_content = "É um pedaço de papel com um vaso de flores vazio nele... É exatamente igual ao que eu tenho em casa!",
  ui_story_5055_50559902_3_dialog_content = "Exceto que este está vazio... Não há nada crescendo nele.",
  ui_story_5055_50559902_4_dialog_content = "Se ao menos eu tivesse a semente certa para isso...",
  ui_story_5055_50559902_5_dialog_content = "Esse pedaço de papel foi rasgado do meu livro de figuras também?",
  ui_story_5055_50559902_6_dialog_content = "Parece que o tamanho está certo, mas a imagem está toda errada.",
  ui_story_5055_50559902_7_dialog_content = "Deveria ser o rosto de alguém importante para mim aqui...",
  ui_story_5055_50559902_8_dialog_content = "Mas não consigo me lembrar de nada. Minha cabeça está tão vazia quanto este vaso de flores!",
  ui_story_5055_50559902_9_dialog_content = "Esquecer as pessoas mais importantes para mim... é como um vaso de flores sem suas flores.",
  ui_story_5055_50559902_10_dialog_content = "Tudo que eu preciso fazer é pensar em uma maneira de encontrar o que estou procurando...",
  ui_story_5055_50559903_1_dialog_content = "<color=#e8d9bb>Uma misteriosa criatura branca!</color>",
  ui_story_5055_50559903_2_dialog_content = "Uh-O que é isso? Nunca vi um sapo branco antes!",
  ui_story_5055_50559903_3_dialog_content = "Eu simplesmente adoro sapos, e um branco como este deve ser super raro!",
  ui_story_5055_50559903_4_dialog_content = "Hmm... mas não parece muito com um sapo - é tão pequeno e tão bonito. Maytalvez seja na verdade uma rã...",
  ui_story_5055_50559903_5_dialog_content = "Você está indo para o lado errado, sapinho, o lago é para lá! Pule no Rediesel Desert por muito tempo e você pode secar.",
  ui_story_5055_50559903_6_dialog_content = "Eu conheço outro lugar onde há água, se você não se importar de vir comigo...",
  ui_story_5055_50559903_7_dialog_content = "Sinceramente, por que você viria a um lugar tão seco e escuro...?",
  ui_story_5055_50559903_8_dialog_content = "... Para encontrar... Eve...",
  ui_story_5055_50559903_9_dialog_content = "?!",
  ui_story_5055_50559903_10_dialog_content = "Ouvi algo agora mesmo... Foi minha imaginação?",
  ui_story_5055_50559904_1_dialog_content = "<color=#e8d9bb>Um brinquedo com uma aparência distinta. Embora seu design básico pareça bastante comum, ele carrega as marcas de um artesanato requintado.</color>",
  ui_story_5055_50559904_2_dialog_content = "Este brinquedo... parece aquele cachorrinho de cabelo vermelho...",
  ui_story_5055_50559904_3_dialog_content = "... Você veio aqui para se juntar a mim naquele lugar do cachorrinho?",
  ui_story_5055_50559904_4_dialog_content = "Está um pouco sujo, mas segurá-lo me faz sentir tão quente por dentro, como abraçar alguém próximo a mim...",
  ui_story_5055_50559904_5_dialog_content = "De repente, sinto um pouco de saudades de casa.",
  ui_story_5055_50559904_6_dialog_content = "Isso é estranho, minha casa não está em algum lugar muito, muito perto?",
  ui_story_5055_50559904_7_dialog_content = "Mas por que será que eu ainda sinto tanta falta da minha família...?",
  ui_story_5055_50559904_8_dialog_content = "Sinto falta de ter aqueles braços grandes e quentes me envolvendo...",
  ui_story_5055_50559905_1_dialog_content = "<color=#e8d9bb>Um item deixado para trás pela criatura branca!</color>",
  ui_story_5055_50559905_2_dialog_content = "Achei que vi uma criaturinha pálida pular na minha frente agora mesmo...",
  ui_story_5055_50559905_3_dialog_content = "Deixou isso?",
  ui_story_5055_50559905_4_dialog_content = "Que tesouro lindo! Deixe-me ver, esta é uma faixa de cabelo super pequena?",
  ui_story_5055_50559905_5_dialog_content = "Parece meio familiar... Onde eu vi isso antes...?",
  ui_story_5055_50559905_6_dialog_content = "... Tô aqui... Eve...",
  ui_story_5055_50559905_7_dialog_content = "Eu realmente ouvi algo! Mas parece que está vindo de um lugar tão estranho...",
  ui_story_5055_50559905_8_dialog_content = "Como... alguém está me chamando de dentro...",
  ui_story_5055_50559906_1_dialog_content = "<color=#e8d9bb>Um pedaço de papel com um padrão colossal de chave inglesa, exalando um ar de poder e estilo.</color>",
  ui_story_5055_50559906_2_dialog_content = "... Esta é... mais uma das minhas pinturas? Este parece uma chave inglesa.",
  ui_story_5055_50559906_3_dialog_content = "Lembro-me de quando meu irmão me deu meu primeiro pincel... A primeira coisa que ele me ensinou a pintar foi esta chave inglesa.",
  ui_story_5055_50559906_4_dialog_content = "Ele ficou tão bravo consigo mesmo quando sua pintura não saiu como queria, que amassou a folha em um acesso de raiva...",
  ui_story_5055_50559906_5_dialog_content = "Mas quando eu pintei um melhor que o dele, ele ficou tão orgulhoso e disse que não estava surpreso que eu pudesse fazer isso, já que sou irmã dele.",
  ui_story_5055_50559906_6_dialog_content = "...",
  ui_story_5055_50559906_7_dialog_content = "... Irmão...",
  ui_story_5055_50559907_1_dialog_content = "<color=#e8d9bb>Uma semente solitária, como um voto solene, aguarda descoberta no canto.</color>",
  ui_story_5055_50559907_2_dialog_content = "Isso é... uma semente de flor?!",
  ui_story_5055_50559907_3_dialog_content = "Lembro-me de como são suas flores!",
  ui_story_5055_50559907_4_dialog_content = "Este é o seu broto, não é? O pequeno amigo que perdi no incêndio...",
  ui_story_5055_50559907_5_dialog_content = "Obrigado. Você sempre esteve lá quando eu mais precisei de você.",
  ui_story_5055_50559907_6_dialog_content = "Mas o que você está fazendo em um lugar assim?! Você vai se queimar!",
  ui_story_5055_50559907_7_dialog_content = "Deixe-me te dar um novo lar - um lugar onde posso mantê-lo seguro! Não vou deixar nada de ruim acontecer com você, prometo!",
  ui_story_5055_50559907_8_dialog_content = "Acho que, há muito tempo, fiz outra promessa...",
  ui_story_5055_50559907_9_dialog_content = "Eu tenho que lembrar!",
  ui_story_5055_50559908_1_dialog_content = "<color=#e8d9bb>Coloque a pequena faixa de cabelo na pequena criatura branca!</color>",
  ui_story_5055_50559908_2_dialog_content = "<color=#e8d9bb>O sapo parece ter crescido após a colocação da tiara nele e começa a emitir um brilho suave.</color>",
  ui_story_5055_50559908_3_dialog_content = "É um ajuste perfeito! Pode ser apenas um pequeno acessório básico...",
  ui_story_5055_50559908_4_dialog_content = "Mas isso meio que faz você parecer mais refinado, como o príncipe sapo naquele livro de contos de fadas com ilustrações.",
  ui_story_5055_50559908_5_dialog_content = "(Aposto que se eu o vestisse direito, daria um príncipe tão bonito!)",
  ui_story_5055_50559908_6_dialog_content = "Ei, onde você acha que está indo?!",
  ui_story_5055_50559908_7_dialog_content = "Não é seguro lá fora! Não saia!",
  ui_story_5055_50559908_8_dialog_content = "... Não se preocupe. Eu sei que você nunca me machucaria.",
  ui_story_5055_50559908_9_dialog_content = "O quê?!",
  ui_story_5055_50559908_10_dialog_content = "... Sua luta... tão difícil. Deixe-me fazer algo por você também!",
  ui_story_5055_50559908_11_dialog_content = "Para que você não tenha que passar por tudo isso sozinho!",
  ui_story_5055_50559909_1_dialog_content = "<color=#e8d9bb>O Colosso da pequena criatura branca!</color>",
  ui_story_5055_50559909_2_dialog_content = "Isso é... Eu lembro! Ele voa pelo céu, majestoso e livre...",
  ui_story_5055_50559909_3_dialog_content = "Já estive dentro dele?",
  ui_story_5055_50559909_4_dialog_content = "... Eu me lembro de uma janela brilhante, com uma vasta extensão azul profundo do lado de fora.",
  ui_story_5055_50559909_5_dialog_content = "Lembro de alguém me dando comida e dizendo palavras gentis para mim.",
  ui_story_5055_50559909_6_dialog_content = "Comecei a correr por dentro dessa coisa... Eu não me sentia tão bem há muito tempo, e então...",
  ui_story_5055_50559909_7_dialog_content = "Uh-",
  ui_story_5055_50559909_8_dialog_content = "Então você parte em uma jornada.",
  ui_story_5055_50559909_9_dialog_content = "Você é-?!",
  ui_story_5055_50559909_10_dialog_content = "Embora tenha enfrentado muitas aventuras inesperadas ao longo do caminho, você estava determinado a cumprir uma promessa importante.",
  ui_story_5055_50559909_11_dialog_content = "... Agora, você está finalmente tão perto de cumprir essa promessa, e há muitas pessoas esperando por você...",
  ui_story_5055_50559910_1_dialog_content = "<color=#e8d9bb>O brinquedo vê a chave inglesa na pintura e pula na página rasgada com entusiasmo desenfreado.</color>",
  ui_story_5055_50559910_2_dialog_content = "<color=#e8d9bb>O brinquedo e a chave inglesa irradiam uma luz quente, como o brilho do sol da manhã. Eve esfrega os olhos e um rosto familiar aparece na imagem.</color>",
  ui_story_5055_50559910_3_dialog_content = "Ahh! É... É meu irmão!",
  ui_story_5055_50559910_4_dialog_content = "Finalmente... Eu finalmente me lembro do rosto do meu irmão!",
  ui_story_5055_50559910_5_dialog_content = "... E... Eve!",
  ui_story_5055_50559910_6_dialog_content = "... É a voz do meu irmão! De onde está vindo...?",
  ui_story_5055_50559910_7_dialog_content = "Seu desejo ardente se manifestou. Embora você possa ouvir sua voz, ele não consegue sentir sua presença.",
  ui_story_5055_50559910_8_dialog_content = "Eve!",
  ui_story_5055_50559910_9_dialog_content = "Sinto muito por tudo que aconteceu antes. Não prestei atenção suficiente em como você realmente se sentia... porque pensei que estava protegendo você, mas... não entendi quanta dor você estava sentindo...",
  ui_story_5055_50559910_10_dialog_content = "Sou um irmão terrível.",
  ui_story_5055_50559910_11_dialog_content = "Não, irmão, eu fui tão teimoso. Eu só... não aguento mais como estou. É por isso...",
  ui_story_5055_50559910_12_dialog_content = "Uma tempestade está chegando, mas não se preocupe—eu prometo que vou te proteger.",
  ui_story_5055_50559910_13_dialog_content = "Não... Sinsa, apenas corra, rapidamente...",
  ui_story_5055_50559910_14_dialog_content = "Vou abrir um buraco nesta tempestade com as minhas mãos e arrastá-lo para fora de lá! Estou trazendo você para casa!",
  ui_story_5055_50559910_15_dialog_content = "Então, se você acha que pode me perdoar um dia, apenas acorde...",
  ui_story_5055_50559910_16_dialog_content = "... A casa está exatamente como você deixou. Todas as suas bonecas favoritas e suas pinturas estão te esperando no seu quarto...",
  ui_story_5055_50559910_17_dialog_content = "...",
  ui_story_5055_50559910_18_dialog_content = "Eve, eu realmente sinto sua falta...",
  ui_story_5055_50559910_19_dialog_content = "... Sinsa... Também sinto saudade...",
  ui_story_5055_50559911_1_dialog_content = "<color=#e8d9bb>Uma semente de flor cai no vaso vazio do livro ilustrado, e uma flor da alvorada desabrocha na página.</color>",
  ui_story_5055_50559911_2_dialog_content = "<color=#e8d9bb>A flor desabrocha com uma luz brilhante, tão deslumbrante quanto o amanhecer. Eve esfrega os olhos e um rosto familiar aparece na página.</color>",
  ui_story_5055_50559911_3_dialog_content = "Dawn! Eu... Eu lembro! É o rosto do meu amigo—aquele que sempre esteve lá por mim... É Dawn!",
  ui_story_5055_50559911_4_dialog_content = "... Eve.",
  ui_story_5055_50559911_5_dialog_content = "... De quem é essa voz? Dawn... Dawn! É você?",
  ui_story_5055_50559911_6_dialog_content = "O desejo ardente dela se manifestou. Você pode ouvir a voz dela, mas suas palavras não podem ser transmitidas a ela.",
  ui_story_5055_50559911_7_dialog_content = "... Eve...",
  ui_story_5055_50559911_8_dialog_content = "... Vendo você assim... Isso me lembra do dia em que nos conhecemos...",
  ui_story_5055_50559911_9_dialog_content = "Naquela fria enfermaria, nossos corpos estavam cobertos de sensores e tubos...",
  ui_story_5055_50559911_10_dialog_content = "Eu... Não sou tão confiável quanto você pensava...",
  ui_story_5055_50559911_11_dialog_content = "Na escuridão e através do medo, tudo o que eu podia fazer era contrair meus músculos e me preparar para a dor... Foi por isso que te ignorei naquela época e por que você quase me entendeu errado.",
  ui_story_5055_50559911_12_dialog_content = "Não, você É confiável, Dawn! E você é a pessoa mais corajosa que eu conheço...",
  ui_story_5055_50559911_13_dialog_content = "Aquele enfermaria era como uma jaula, e você foi o único que ousou desafiar nosso captor diretamente.",
  ui_story_5055_50559911_14_dialog_content = "Foi logo depois disso que percebi que você não era nada mau — você apenas gosta de olhar para as pessoas com essa expressão feroz no rosto.",
  ui_story_5055_50559911_15_dialog_content = "Completamente, totalmente, não horrível.",
  ui_story_5055_50559911_16_dialog_content = "... Eu amava ouvir suas histórias. Sua voz, suas palavras... Elas carregavam a beleza do mundo que eu ansiava ver e a apresentavam diante dos meus olhos.",
  ui_story_5055_50559911_17_dialog_content = "...Embora tenha sido um pouco estranho sempre que você esquecia o que deveria vir a seguir...",
  ui_story_5055_50559911_18_dialog_content = "Mas as histórias em si nunca foram tão importantes quanto simplesmente ter você ao meu lado...",
  ui_story_5055_50559911_19_dialog_content = "Você deu água à flor, você me deu um nome...",
  ui_story_5055_50559911_20_dialog_content = "Eu realmente gosto desse nome... Dawn... Dawn...",
  ui_story_5055_50559911_21_dialog_content = "Então, você precisa acordar em breve, tá bom?",
  ui_story_5055_50559911_22_dialog_content = "Lembre-se da promessa que fizemos—de assistir juntos ao momento em que a flor da alvorada desabrocha...",
  ui_story_5055_50559911_23_dialog_content = "Dawn, eu ainda me lembro... Eu me lembro de tudo... *soluço* Foi horrível.",
  ui_story_5055_50559911_24_dialog_content = "Dawn ainda está lá no campo de flores ao amanhecer esperando eu encontrá-la!",
  ui_story_5055_50559912_1_dialog_content = "<color=#e8d9bb>O príncipe sapo branco pula para dentro da imagem e se senta bem em cima do Colosso.</color>",
  ui_story_5055_50559912_2_dialog_content = "<color=#e8d9bb>As asas brancas do Colossus se estendem em um arco, como uma barragem de meteoros alcançando o horizonte. Eve esfrega os olhos e um rosto familiar aparece na página.</color>",
  ui_story_5055_50559912_3_dialog_content = "... Eu conheço você!",
  ui_story_5055_50559912_4_dialog_content = "Rua Cauda, Eclipsitas, Irmão, Dawn e as pessoas que enfrentaram essas memórias comigo...",
  ui_story_5055_50559912_5_dialog_content = "PlayerName, eu me lembro de você!",
  ui_story_5055_50559912_6_dialog_content = "Foi você o tempo todo, constantemente falando comigo, me impulsionando neste sonho com informações do mundo exterior...",
  ui_story_5055_50559912_7_dialog_content = "Acompanhando-me enquanto eu vasculhava meu passado para encontrar a dor, a raiva, o medo dentro de mim...",
  ui_story_5055_50559912_8_dialog_content = "Even se todos estão amaldiçoados na parte mais profunda deste sonho distorcido...",
  ui_story_5055_50559912_9_dialog_content = "Onde o irmão se transformou em um cachorro grande, Dawn se transformou em uma flor e uma bruxa má te transformou em um sapinho...",
  ui_story_5055_50559912_10_dialog_content = "Você ainda me encontrou! Você não podia me deixar enfrentar esse pesadelo sozinho!",
  ui_story_5055_50559912_11_dialog_content = "Você é o meu príncipe sapo, não é?",
  ui_story_5055_50559912_12_dialog_content = "... Se isso é verdade, então deixe-me fazer uma pergunta.",
  ui_story_5055_50559912_13_dialog_content = "Suas memórias caóticas foram acalmadas e a maldição do seu príncipe foi quebrada.",
  ui_story_5055_50559912_14_dialog_content = "Certamente a princesa também quer se libertar da maldição da bruxa e enfrentar seu verdadeiro eu, não é?",
  ui_story_5055_50559912_15_dialog_content = "Meu verdadeiro eu...",
  ui_story_5055_50559912_16_dialog_content = "Me diga, o que você mais deseja agora mesmo?",
  ui_story_5055_50559912_17_dialog_content = "Quero te ver!",
  ui_story_5055_50559912_18_dialog_content = "Eu quero ver Dawn e meu irmão! Eu quero ver Vice e todos que cuidaram de mim na Rediesel Wrench!",
  ui_story_5055_50559912_19_dialog_content = "Sinto muita falta de todos vocês... Mayapesar de não ter sido tanto tempo assim para vocês aí fora.",
  ui_story_5055_50559912_20_dialog_content = "Mas sinto que estou sozinho aqui há tanto tempo!",
  ui_story_5055_50559912_21_dialog_content = "PlayerName, você pode me levar de volta com você?",
  ui_story_5055_50559912_22_dialog_content = "Sua força o guiará de volta.",
  ui_story_5055_50559912_23_dialog_content = "Espere... Você está me deixando?",
  ui_story_5055_50559912_24_dialog_content = "(Não se esqueça... do seu amor.)"
}
return config
